// ============================================================================
// N8N CODE NODE : CALCUL DES JOURS DE RETARD ET DU NIVEAU DE RELANCE (ODOO)
// ============================================================================

const items = $input.all();
const now = new Date();
const todayUtcMidnight = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const MS_PER_DAY = 1000 * 60 * 60 * 24;

// Extrait l'id ou le nom d'un champ relationnel Odoo ([id, "Nom"] ou id direct)
const relId = (v) => (Array.isArray(v) ? v[0] : v ?? null);
const relName = (v) => (Array.isArray(v) ? v[1] : null);

const results = [];

for (const item of items) {
  const data = item.json || {};
  const dueDateRaw = data.invoice_date_due;

  // Ignore les factures sans date d'échéance exploitable
  if (!dueDateRaw) continue;

  const parsedDue = new Date(dueDateRaw);
  if (Number.isNaN(parsedDue.getTime())) continue;

  const dueUtcMidnight = Date.UTC(
    parsedDue.getUTCFullYear(),
    parsedDue.getUTCMonth(),
    parsedDue.getUTCDate()
  );

  // Jours de retard
  const daysOverdue = Math.floor((todayUtcMidnight - dueUtcMidnight) / MS_PER_DAY);

  // Pas encore en retard
  if (daysOverdue < 1) continue;

  // Dernier niveau de relance enregistré dans Odoo (0 si jamais relancé ou champ absent)
  const lastReminderLevel = Number(data.soley_last_reminder_level || 0);

  // Client et commercial
  const partnerId = relId(data.partner_id);
  const partnerName = relName(data.partner_id) || data.invoice_partner_display_name || data.name_partner || 'Client';
  const salesperson = data.user_id ?? data.invoice_user_id;   // user_id vient du partenaire (si fusionné)
  const salespersonId = relId(salesperson);
  const salespersonName = relName(salesperson);

  // Uniquement les champs utiles à l'exercice (au lieu de ...data)
  const base = {
    invoice_id: data.id,
    invoice_number: data.name,
    invoice_origin: data.invoice_origin ?? null,
    invoice_date: data.invoice_date ?? null,
    invoice_date_due: data.invoice_date_due,
    amount_total: data.amount_total,
    amount_residual: data.amount_residual,
    currency: relName(data.currency_id) ?? data.currency_id ?? null,
    payment_state: data.payment_state,
    partner_id: partnerId,
    partner_name: partnerName,
    partner_email: data.email ?? null,     // présent si fusionné avec res.partner
    partner_phone: data.phone ?? null,     // présent si fusionné avec res.partner
    salesperson_id: salespersonId,
    salesperson_name: salespersonName,
    days_overdue: daysOverdue,
  };

  // Impayés > 365 jours -> recouvrement manuel (pas de relance auto)
  if (daysOverdue > 365) {
    results.push({
      json: {
        ...base,
        last_reminder_level: lastReminderLevel,
        reminder_level: null,
        reminder_label: 'RECOUVREMENT_MANUEL',
        routing_action: 'MANUAL_RECOVERY',
        should_send_reminder: false,
      },
    });
    continue;
  }

  // Niveau cible selon les seuils
  let targetLevel = 0;
  let reminderLabel = '';

  if (daysOverdue >= 30) {
    targetLevel = 4;
    reminderLabel = 'ESCALADE_J30';
  } else if (daysOverdue >= 15) {
    targetLevel = 3;
    reminderLabel = 'MISE_EN_DEMEURE_DOUCE_J15';
  } else if (daysOverdue >= 7) {
    targetLevel = 2;
    reminderLabel = 'RELANCE_J7';
  } else if (daysOverdue >= 1) {
    targetLevel = 1;
    reminderLabel = 'RAPPEL_COURTOIS_J1';
  }

  // Ignorer si ce niveau (ou un niveau supérieur) a déjà été envoyé
  if (targetLevel <= lastReminderLevel) continue;

  results.push({
    json: {
      ...base,
      last_reminder_level: lastReminderLevel,
      reminder_level: targetLevel,
      reminder_label: reminderLabel,
      routing_action: `LEVEL_${targetLevel}`,
      should_send_reminder: true,
    },
  });
}

return results;

